import{c as t,Q as a,j as i,m as o}from"./chunks/framework.W-g_WCNV.js";const m=JSON.parse('{"title":"Immich","description":"Sign in to Immich with GateKeeper, on the web and in the mobile app.","frontmatter":{"title":"Immich","description":"Sign in to Immich with GateKeeper, on the web and in the mobile app."},"headers":[],"relativePath":"integrations/immich.md","filePath":"integrations/immich.md"}'),s={name:"integrations/immich.md"};function n(r,e,d,c,h,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="immich" tabindex="-1">Immich <a class="header-anchor" href="#immich" aria-label="Permalink to &quot;Immich&quot;">​</a></h1><p><a href="https://immich.app" target="_blank" rel="noreferrer">Immich</a> supports OpenID Connect, so it can use GateKeeper as its identity provider for both the web interface and the iOS and Android apps.</p><p>The mobile app receives its authorization code on a custom address, <code>app.immich:///oauth-callback</code>, rather than an ordinary web address. GateKeeper accepts that as long as it is registered on the client, which it detects automatically. Nothing extra needs enabling.</p><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Mobile sign-in needs GateKeeper v0.9.4 or newer. Earlier versions refuse custom schemes and reject the app with <code>redirect_uri is using a custom schema and is not allowed</code>. Web sign-in works on any version.</p></div><h2 id="step-1-create-the-client-in-gatekeeper" tabindex="-1">Step 1 - create the client in GateKeeper <a class="header-anchor" href="#step-1-create-the-client-in-gatekeeper" aria-label="Permalink to &quot;Step 1 - create the client in GateKeeper&quot;">​</a></h2><p>In the admin panel go to <strong>OIDC Clients</strong> and click <strong>New client</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td><code>Immich</code></td></tr><tr><td>Client ID</td><td><code>immich</code></td></tr><tr><td>Client secret</td><td>Generate one and copy it</td></tr></tbody></table><p>Add <strong>three</strong> redirect URIs, replacing <code>immich.example.com</code> with your own address:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://immich.example.com/auth/login</span></span>
<span class="line"><span>https://immich.example.com/user-settings</span></span>
<span class="line"><span>app.immich:///oauth-callback</span></span></code></pre></div><p>All three are required:</p><ul><li><code>/auth/login</code> completes sign-in on the web.</li><li><code>/user-settings</code> is used when an existing Immich account links itself to OAuth.</li><li><code>app.immich:///oauth-callback</code> is the mobile app. Note the three slashes.</li></ul><p>If you reach Immich over plain HTTP on a local network, use <code>http://</code> in the first two. GateKeeper allows that for a client that also registers a mobile address.</p><p>Save the client, then open the <strong>Test</strong> dialog from the client row. <strong>Application type</strong> should read <em>Native</em>, which confirms the mobile address was recognised.</p><h2 id="step-2-configure-immich" tabindex="-1">Step 2 - configure Immich <a class="header-anchor" href="#step-2-configure-immich" aria-label="Permalink to &quot;Step 2 - configure Immich&quot;">​</a></h2><p>In Immich go to <strong>Administration → Settings → Authentication → OAuth</strong> and set:</p><table tabindex="0"><thead><tr><th>Immich setting</th><th>Value</th></tr></thead><tbody><tr><td>Enabled</td><td>On</td></tr><tr><td>Issuer URL</td><td><code>https://auth.example.com</code></td></tr><tr><td>Client ID</td><td><code>immich</code></td></tr><tr><td>Client Secret</td><td>The secret from step 1</td></tr><tr><td>Scope</td><td><code>openid email profile</code></td></tr><tr><td>ID Token Signed Response Alg</td><td><code>RS256</code></td></tr><tr><td>Userinfo Signed Response Alg</td><td><code>none</code></td></tr><tr><td>Button Text</td><td><code>Sign in with GateKeeper</code></td></tr><tr><td>Auto Register</td><td>On</td></tr><tr><td>Mobile Redirect URI Override</td><td>Leave empty</td></tr></tbody></table><p>The issuer is your GateKeeper base URL on its own. Immich appends <code>.well-known/openid-configuration</code> during discovery, so do not include that part yourself.</p><p><code>RS256</code> and <code>none</code> are the defaults and match what GateKeeper does: identity tokens are signed RS256, and the userinfo response is returned as plain JSON rather than a signed token.</p><p>Save, then sign out and use the new button on the Immich login page.</p><h2 id="mobile-app" tabindex="-1">Mobile app <a class="header-anchor" href="#mobile-app" aria-label="Permalink to &quot;Mobile app&quot;">​</a></h2><p>No separate configuration is needed. Once <code>app.immich:///oauth-callback</code> is registered on the GateKeeper client, open the Immich app, point it at your server, and choose the OAuth button. The app opens a browser, you sign in to GateKeeper, and the browser hands control back to the app.</p><h3 id="if-the-app-cannot-open-the-custom-address" tabindex="-1">If the app cannot open the custom address <a class="header-anchor" href="#if-the-app-cannot-open-the-custom-address" aria-label="Permalink to &quot;If the app cannot open the custom address&quot;">​</a></h3><p>Some devices refuse to hand a custom address back to an app. Immich provides a way around this that does not involve GateKeeper: it serves <code>/api/oauth/mobile-redirect</code>, which forwards to <code>app.immich:///oauth-callback</code>.</p><p>To use it, add that address to the GateKeeper client as a fourth redirect URI:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://immich.example.com/api/oauth/mobile-redirect</span></span></code></pre></div><p>and set <strong>Mobile Redirect URI Override</strong> in Immich to the same value. Sign-in then travels over ordinary HTTPS the whole way.</p><h2 id="optional-claims" tabindex="-1">Optional claims <a class="header-anchor" href="#optional-claims" aria-label="Permalink to &quot;Optional claims&quot;">​</a></h2><p>Immich can read extra values from the identity token. GateKeeper supplies these out of the box:</p><table tabindex="0"><thead><tr><th>Claim</th><th>Value GateKeeper sends</th></tr></thead><tbody><tr><td><code>sub</code></td><td>The user&#39;s GateKeeper ID, which Immich uses to match accounts</td></tr><tr><td><code>email</code></td><td>The user&#39;s email address</td></tr><tr><td><code>email_verified</code></td><td>Whether the address was confirmed by an emailed code</td></tr><tr><td><code>preferred_username</code></td><td>The user&#39;s email address</td></tr><tr><td><code>groups</code></td><td>The names of every group the user belongs to</td></tr></tbody></table><p>Immich&#39;s <strong>Storage Label Claim</strong> defaults to <code>preferred_username</code>, so uploads are filed under the user&#39;s email address. Leave it, or point it at a custom claim if you want something shorter.</p><p>To send anything else, use <strong>Custom claims</strong> on the GateKeeper client. A claim can carry the user&#39;s ID, email, display name, group membership, or a fixed string.</p><div class="warning custom-block"><p class="custom-block-title">Role and quota claims</p><p>Immich&#39;s <strong>Role Claim</strong> expects a single value of <code>user</code> or <code>admin</code>, and <strong>Storage Quota Claim</strong> expects a number. GateKeeper can only send a fixed string or the full group list for a claim, so neither can be varied per user today. Leave both unset and manage administrators and quotas inside Immich.</p></div><h2 id="restricting-who-can-sign-in" tabindex="-1">Restricting who can sign in <a class="header-anchor" href="#restricting-who-can-sign-in" aria-label="Permalink to &quot;Restricting who can sign in&quot;">​</a></h2><p>By default anyone with a GateKeeper account can sign in to Immich, and Auto Register creates an Immich account for them on first use.</p><p>To limit it, create an access policy such as <code>photos</code>, add the users who should have access, and attach it to the Immich client. Everyone else is stopped at GateKeeper with an access denied page and never reaches Immich. See <a href="/admin/policies.html">Access policies</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong><code>redirect_uri is using a custom schema and is not allowed</code></strong></p><p>The mobile address is not registered on the client, or GateKeeper is older than v0.9.4. Add <code>app.immich:///oauth-callback</code> to the client and confirm the Test dialog reports the application type as <em>Native</em>.</p><p><strong><code>The requested redirect_uri is missing in the client configuration</code></strong></p><p>Immich sent an address that is not on the client. The comparison is exact, so a trailing slash or <code>http</code> where you registered <code>https</code> will fail. Copy the address out of the error and add it verbatim.</p><p><strong>Signing in returns to the Immich login page</strong></p><p>Immich could not identify the user from the response. Check that the scope is <code>openid email profile</code>, since Immich matches accounts on the email address.</p><p><strong>The mobile app opens the browser and then stops</strong></p><p>The device did not pass the custom address back to the app. Use the mobile redirect override described above.</p>`,44)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
